() => {
  const link = document.querySelector('a[data-testid="internal-link"][href*="/news/articles/"]');
  if (link) {
    return { href: link.href, text: link.textContent.trim().substring(0, 200) };
  }
  // Fallback: find any Trump-related article link
  const allLinks = document.querySelectorAll('a');
  const trumpLinks = [];
  allLinks.forEach(a => {
    if (a.href && a.href.includes('bbc.com/news/articles/') && a.textContent.toLowerCase().includes('trump')) {
      trumpLinks.push({ href: a.href, text: a.textContent.trim().substring(0, 200) });
    }
  });
  return { trumpLinks: trumpLinks.slice(0, 5) };
}

() => {
  const links = Array.from(document.querySelectorAll('a[data-testid="internal-link"]')).slice(0, 10);
  return links.map(a => ({ href: a.href, text: a.textContent.trim().substring(0, 150) }));
}

() => {
  const links = Array.from(document.querySelectorAll('a[data-testid="internal-link"]'));
  const trumpLinks = [];
  links.forEach(a => {
    if (a.textContent.toLowerCase().includes('trump')) {
      trumpLinks.push({ href: a.href, text: a.textContent.trim().substring(0, 200) });
    }
  });
  return JSON.stringify(trumpLinks.slice(0, 10));
}

() => {
  // Find links related to Trump-Xi welcome story
  const links = Array.from(document.querySelectorAll('a'));
  const found = links.find(a => a.textContent.includes('Xi got Trump'));
  if (found) return found.href;
  return 'not found';
}

() => {
  const links = Array.from(document.querySelectorAll('a'));
  for (const a of links) {
    if (a.textContent.includes("Xi got Trump's red carpet welcome")) {
      a.click();
      return 'clicked';
    }
  }
  return 'not found';
}

() => {
  const overlay = document.querySelector('[role="dialog"]') || document.querySelector('.modal');
  if (overlay) {
    const closeBtn = overlay.querySelector('button[aria-label*="lose"], button[aria-label*="ismiss"]');
    if (closeBtn) closeBtn.click();
    else overlay.style.display = 'none';
  }
  document.body.style.overflow = 'auto';
  return 'modal dismissed';
}

() => {
  const event = new KeyboardEvent('keydown', { key: 'Escape', code: 'Escape', keyCode: 27, which: 27, bubbles: true });
  document.dispatchEvent(event);
  return 'pressed escape';
}

() => {
  // Try to navigate to the article directly using URL fragment
  window.location.hash = '';
  // Scroll to top
  window.scrollTo(0, 0);
  return window.location.href;
}

() => {
  // Remove any overlay modals
  const overlays = document.querySelectorAll('div[class*="overlay"], div[class*="modal"], div[class*="popup"]');
  overlays.forEach(o => o.remove());
  // Remove the obscuring div
  const obscuring = document.querySelectorAll('[role="dialog"]');
  obscuring.forEach(o => o.remove());
  return 'cleared overlays: ' + (overlays.length + obscuring.length);
}
